def set_levels(apps, schema_editor):
    """
    Collaborators: superusers become platform owners; the other staff users
    (who decided on registrations) platform managers, out of /admin/, which
    is for owners only now. Each change goes to the platform log.
    """
    User = apps.get_model("core", "User")
    PlatformLog = apps.get_model("core", "PlatformLog")
    for user in User.objects.filter(
        models.Q(is_superuser=True) | models.Q(is_staff=True)
    ):
        role = "owner" if user.is_superuser else "manager"
        user.platform_role = role
        user.is_staff = user.is_superuser
        user.save(update_fields=["platform_role", "is_staff"])
        name = (
            f"{user.full_name} <{user.email}>"
            if user.full_name
            else user.email or user.admin_email or ""
        )
        PlatformLog.objects.create(
            action="role_changed",
            target=user,
            target_name=name,
            details={"previous": "collaborator", "role": role, "source": "migration"},
        )


